package com.travbook.journeys.adapter.out.persistence;
import com.travbook.journeys.application.port.out.JourneySupplier;
import com.travbook.journeys.domain.model.Journey.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.ObjectMapper;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
/** Deterministic provider simulator with its own durable inventory and operation ledger. */
public final class JdbcJourneySupplier implements JourneySupplier,com.travbook.journeys.application.port.out.JourneyCabDispatch,com.travbook.buses.application.port.in.BusInventory {
 private final JdbcClient jdbc;private final TransactionTemplate tx;private final ObjectMapper json;private final Clock clock;
 public JdbcJourneySupplier(JdbcClient j,TransactionTemplate t,ObjectMapper m,Clock c){jdbc=j;tx=t;json=m;clock=c;}
 public Optional<Current> current(UUID id){outside();return tx.execute(t->{guard("journey-supplier:"+id);return jdbc.sql("select r.status,r.resource,(select count(*) from journey_supplier_component c where c.booking_id=r.booking_id and c.status='CONFIRMED') components,(select count(*) from journey_supplier_seat s where s.booking_id=r.booking_id and (s.confirmed or s.expires_at>:now)) seats from journey_supplier_reservation r where r.booking_id=:id").param("id",id).param("now",Timestamp.from(clock.instant())).query((r,n)->new Current(id,r.getString("status"),r.getString("resource"),r.getInt("components"),r.getInt("seats"),"MOCK")).optional();});}
 public Set<String> unavailable(String supplier,UUID trip,Instant now){return Set.copyOf(jdbc.sql("select seat from journey_supplier_seat where resource=:r and (confirmed or expires_at>:now)").param("r",supplier+":"+trip).param("now",Timestamp.from(now)).query(String.class).list());}
 public void validateHold(Booking b){outside();b.quote().valid(clock.instant());boolean held=jdbc.sql("select count(*) from journey_supplier_seat s join journey_supplier_reservation r on r.booking_id=s.booking_id where s.booking_id=:id and r.status='HELD' and s.expires_at>:now").param("id",b.id()).param("now",Timestamp.from(clock.instant())).query(Integer.class).single()==b.quote().selection().request().seats().size();if(!held)throw new com.travbook.shared.domain.DomainFailure(com.travbook.shared.domain.DomainFailure.Code.OFFER_UNAVAILABLE,"The supplier seat hold expired or was lost.");}
 private void outside(){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("Provider effect inside orchestration transaction");}
 public Optional<Receipt> lookup(UUID id){outside();return jdbc.sql("select payload::text from journey_supplier_receipt where operation_id=:id").param("id",id).query(String.class).optional().map(s->json.readValue(s,Receipt.class));}
 private String fingerprint(Booking b){return b.supplierFingerprint();}
 private void guard(String key){jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key",key).query((r,n)->true).single();}
 public Receipt execute(Booking b,Step step){outside();return tx.execute(t->{guard("journey-supplier:"+b.id());var old=jdbc.sql("select payload::text from journey_supplier_receipt where operation_id=:id").param("id",b.operation(step)).query(String.class).optional();if(old.isPresent()){var r=json.readValue(old.get(),Receipt.class);if(!r.fingerprint().equals(fingerprint(b))||!r.bookingId().equals(b.id())||r.step()!=step)throw new IllegalStateException("Provider idempotency mismatch");return r;}
  var q=b.quote();var s=q.selection();String resource=s.supplier()+":"+s.resource();guard("journey-resource:"+resource);var state=jdbc.sql("select status from journey_supplier_reservation where booking_id=:id for update").param("id",b.id()).query(String.class).optional().orElse(null);boolean accepted;
  switch(step){
   case HOLD->{if(s.request().kind()!=Kind.BUS)throw new IllegalStateException("Holds are only supported for buses");jdbc.sql("delete from journey_supplier_seat where resource=:r and not confirmed and expires_at<=:now").param("r",resource).param("now",Timestamp.from(clock.instant())).update();accepted=clock.instant().isBefore(q.expiresAt());for(String seat:s.request().seats())if(jdbc.sql("select count(*) from journey_supplier_seat where resource=:r and seat=:s").param("r",resource).param("s",seat).query(Integer.class).single()>0)accepted=false;insert(b,resource,accepted?"HELD":"REJECTED");if(accepted)for(String seat:s.request().seats())jdbc.sql("insert into journey_supplier_seat(resource,seat,booking_id,expires_at) values(:r,:s,:id,:at)").param("r",resource).param("s",seat).param("id",b.id()).param("at",Timestamp.from(q.expiresAt())).update();}
   case RESERVE->{accepted=clock.instant().isBefore(q.expiresAt())&&b.scenario()!=Scenario.RESERVATION_REJECTED;if(s.request().kind()==Kind.BUS){accepted=accepted&&"HELD".equals(state)&&jdbc.sql("select count(*) from journey_supplier_seat where booking_id=:id and expires_at>:now").param("id",b.id()).param("now",Timestamp.from(clock.instant())).query(Integer.class).single()==s.request().seats().size();if(state==null)throw new IllegalStateException("Bus hold receipt missing");update(b.id(),accepted?"CONFIRMED":"REJECTED");if(accepted)jdbc.sql("update journey_supplier_seat set confirmed=true where booking_id=:id").param("id",b.id()).update();}else insert(b,resource,accepted?"CONFIRMED":"REJECTED");if(accepted)for(var c:s.components())jdbc.sql("insert into journey_supplier_component(booking_id,component_id,status,amount,currency) values(:id,:component,'CONFIRMED',:amount,'INR')").param("id",b.id()).param("component",c.id()).param("amount",c.amount().decimal()).update();}
   case RELEASE->{if("CONFIRMED".equals(state))throw new IllegalStateException("Cannot release confirmed reservation");accepted=true;if(state!=null)update(b.id(),"RELEASED");jdbc.sql("delete from journey_supplier_seat where booking_id=:id and not confirmed").param("id",b.id()).update();}
   case CANCEL->{if(!"CONFIRMED".equals(state))throw new IllegalStateException("Cancellation requires known confirmed reservation");accepted=true;update(b.id(),"CANCELLED");jdbc.sql("delete from journey_supplier_seat where booking_id=:id").param("id",b.id()).update();jdbc.sql("update journey_supplier_component set status='CANCELLED' where booking_id=:id").param("id",b.id()).update();}
   default->throw new IllegalStateException("Unsupported supplier operation");
  }
  if(step==Step.RESERVE&&accepted&&q.version()==2&&s.request().kind()==Kind.CAB){var dispatch=com.travbook.journeys.domain.model.Care.Dispatch.assigned(b.id(),clock.instant());jdbc.sql("insert into journey_supplier_dispatch(booking_id,version,payload) values(:id,1,cast(:p as jsonb))").param("id",b.id()).param("p",json.writeValueAsString(dispatch)).update();}
  var receipt=new Receipt(b.operation(step),b.id(),step,fingerprint(b),accepted,"MOCK-JOURNEY-"+b.id(),"MOCK");jdbc.sql("insert into journey_supplier_receipt(operation_id,booking_id,step,payload) values(:op,:id,:step,cast(:p as jsonb))").param("op",receipt.operationId()).param("id",b.id()).param("step",step.name()).param("p",json.writeValueAsString(receipt)).update();return receipt;});}
 private void insert(Booking b,String resource,String status){jdbc.sql("insert into journey_supplier_reservation(booking_id,kind,resource,status,expires_at,payload) values(:id,:kind,:r,:s,:at,cast(:p as jsonb))").param("id",b.id()).param("kind",b.quote().selection().request().kind().name()).param("r",resource).param("s",status).param("at",Timestamp.from(b.quote().expiresAt())).param("p",json.writeValueAsString(Map.of("selection",b.quote().selection(),"passengers",b.passengers()))).update();}
 private void update(UUID id,String status){jdbc.sql("update journey_supplier_reservation set status=:s where booking_id=:id").param("s",status).param("id",id).update();}

 public com.travbook.journeys.domain.model.Care.Dispatch get(UUID id){outside();return tx.execute(t->{guard("journey-supplier:"+id);return dispatchRecord(id);});}
 private com.travbook.journeys.domain.model.Care.Dispatch dispatchRecord(UUID id){var status=jdbc.sql("select status from journey_supplier_reservation where booking_id=:id").param("id",id).query(String.class).optional().orElse("NONE");if(!status.equals("CONFIRMED"))return com.travbook.journeys.domain.model.Care.Dispatch.unavailable(id,clock.instant(),status.equals("CANCELLED"));return jdbc.sql("select payload::text from journey_supplier_dispatch where booking_id=:id").param("id",id).query(String.class).optional().map(p->json.readValue(p,com.travbook.journeys.domain.model.Care.Dispatch.class)).orElseGet(()->com.travbook.journeys.domain.model.Care.Dispatch.unavailable(id,clock.instant(),false));}
 public com.travbook.journeys.domain.model.Care.Dispatch advance(UUID owner,UUID id,long version,String key){outside();return tx.execute(t->{guard("dispatch-command:"+owner+":"+key);guard("journey-supplier:"+id);String f=id+":"+version;var prior=jdbc.sql("select fingerprint,payload::text from journey_dispatch_command where customer_id=:owner and command_key=:key").param("owner",owner).param("key",key).query((r,n)->{if(!r.getString(1).equals(f))throw new com.travbook.shared.domain.DomainFailure(com.travbook.shared.domain.DomainFailure.Code.IDEMPOTENCY_CONFLICT,"Dispatch key changed.");return json.readValue(r.getString(2),com.travbook.journeys.domain.model.Care.Dispatch.class);}).optional();if(prior.isPresent())return prior.get();var next=dispatchRecord(id).advance(version,clock.instant());if(jdbc.sql("update journey_supplier_dispatch set version=:v,payload=cast(:p as jsonb) where booking_id=:id and version=:old").param("v",next.version()).param("p",json.writeValueAsString(next)).param("id",id).param("old",version).update()!=1)throw new IllegalStateException("Dispatch contention");jdbc.sql("insert into journey_dispatch_command(customer_id,command_key,fingerprint,payload) values(:owner,:key,:f,cast(:p as jsonb))").param("owner",owner).param("key",key).param("f",f).param("p",json.writeValueAsString(next)).update();return next;});}
}
